"""Event-grouped contextual ledger from independently read available bodies."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).resolve().parent
D=json.loads((ROOT/'wb_review_decisions.json').read_text())
rows=[]
def add(aid,event_key,group,date,place,person,force,taker,owner,stage,individual,expanded,custody,context):
 r=dict(event_key=event_key,context_group=group,event_date=date,event_date_note=D[aid]['event_date_basis'],actual_state='West Bengal',place=place,person=person,force=force,weapon_taking_actor=taker,weapon_owner=owner,taking_claim_stage=stage,deceased_individually_alleged_to_take_weapon=individual,strict_state_police_individual_mechanism='no',expanded_security_force_individual_mechanism=expanded,custody_or_crime_reconstruction=custody,outcome=D[aid]['outcome'],article_ids=aid,source_url=f'https://timesofindia.indiatimes.com/articleshow/{aid}.cms',source_context=context,evidence_status='TOI-reported account; independent truth not established; AI source-context review, not human gold standard')
 rows.append(r)
